import { useErrorBoundary } from '@suspensive/react';
import { Fragment } from 'react';
import ReactPlayer from 'react-player';
import { useSearchParams } from 'react-router-dom';
import { 처리중Context } from '~/widgets/exchange-remittance-funnel/model/schemas';
import { useSetHeaderLeft } from '~/widgets/sub-layout/use-sub-layout';
import { useExchangeProcessVideo } from '~/features/load-video/use-exchange-process-video';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { RemitRequestDTO } from '~/entities/exchange/api/dtos/types';
import { useCancelReceiptMutation } from '~/entities/exchange/api/hooks/use-cancel-receipt-mutation';
import { useRemitDC1TrnscExecuteMutation } from '~/entities/exchange/api/hooks/use-remit-dc1-trnsc-execute-mutation';
import { useUpdateRemitStatusMutation } from '~/entities/exchange/api/hooks/use-update-remit-status';
import { PhaseType } from '~/entities/exchange/model/constants';
import { ConfirmInfo } from '~/entities/exchange-input-confirm/ui/confirm-info';
import { pollTransactionStatus } from '~/entities/exchange-process';
import { findTokenItemById, getTokenItemLabel } from '~/entities/user';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { getExchangeTransactionLabel } from '~/entities/wallet/lib/get-trnsc-type-label';
import { TokenItemType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { statusHandlers } from '~/entities/exchange-process/lib/use-transaction-status';

type ProcessPageProps = {
  context: 처리중Context;
  onNext: (params: { trnscId: string; reqAliasNm: string }) => void;
  onError: (error: Error) => void;
};

export const ProcessPage = ({ onNext, onError, context }: ProcessPageProps) => {
  const { movUrl } = useExchangeProcessVideo({ trnscTypeCd: context.trnscTypeCd });
  const { mutateAsync: remitDC1Execute } = useRemitDC1TrnscExecuteMutation();
  const { mutateAsync: cancelReceipt } = useCancelReceiptMutation();
  const { mutateAsync: updateRemitStatus } = useUpdateRemitStatusMutation();
  const { data: userRes } = useGetUserInfoQuery();
  const [searchParams] = useSearchParams();
  const historyId = searchParams.get('historyId');
  const isRefund = searchParams.get('isRefund');
  const issuedReceipt = searchParams.get('issuedReceipt');
  const { setError } = useErrorBoundary();

  /**
   * 송금 요청 처리 함수
   */
  const requestRemittance = async () => {
    if (!context.txCd) {
      setError(new Error('txCode가 없습니다.'));
      return;
    }

    const params: RemitRequestDTO = {
      tbAcnutMastr: {
        txCd: context?.txCd,
      },
    };

    const remitRes = await remitDC1Execute(params);
    if (isRefund === 'true') {
      //환불송금시 기존 결제건 상태업데이트 (보류/ 수정필요)
      const udtStatusParam = {
        trnscId: historyId,
        refundTrnscId: remitRes?.payload?.txDbId,
      };
      await updateRemitStatus(udtStatusParam);
      //현금영수증 발급 이력이 있을 경우 현금영수증 취소
      if (issuedReceipt === 'true') {
        await cancelReceipt({ trnscId: historyId, refundTrnscId: remitRes?.payload?.txDbId });
      }
      return remitRes;
    }
    return remitRes;
  };

  /**
   * 비디오 종료 후 호출되는 이벤트 핸들러
   */
  const handleEventChange = async () => {
    try {
      const requestResult = await requestRemittance();
      // 트랜잭션 ID가 문자열인 경우 폴링 시작
      if (requestResult && typeof requestResult.requestId === 'string') {
        // const handlers = statusHandlers(requestResult.requestId, {
        //   onNext,
        //   onError,
        // });
        const handlers = statusHandlers(
          requestResult.requestId,
          requestResult.payload?.aliasNm ?? context.aliasNm ?? '',
          {
            onNext,
            onError,
          },
        );

        // Execute the appropriate handler based on status or use default
        handlers[requestResult?.status as keyof typeof handlers]();
      } else {
        const error = new Error('송금 오류');
        onError(error);
      }
    } catch (error) {
      onError(error instanceof Error ? error : new Error('Failed to process remittance'));
    }
  };

  useSetHeaderLeft(<></>);

  const transactionLabel = getExchangeTransactionLabel(context.trnscTypeCd);
  const tokenItem = findTokenItemById(userRes?.tbCstmrMastr?.tokenList, context.tokenId);
  const usingTokenLabel = getTokenItemLabel(tokenItem);
  const { shortBankName: recipientBankName } = useComBankInfo(context?.recipientData?.insttCd);

  return (
    <div className="wrap bgw">
      <div className="content sub">
        <ConfirmInfo amount={Number(context.trnscAmt)} phase={PhaseType.Process} transactionLabel={transactionLabel}>
          <Fragment>
            {i18n.t('text:toX', { x: context.personNm })}
            <br />
            <button type="button" className={`wallet-account no-btn dark ${context.walletInsttCd}`}>
              {recipientBankName} {context.aliasNm}
            </button>
            {usingTokenLabel && <span className="token">{usingTokenLabel}</span>}
          </Fragment>
        </ConfirmInfo>
        <div className="result-area">
          <div className="process">
            <div className="process-mov">
              <ReactPlayer
                url={movUrl}
                width="250px"
                height="250px"
                playing={true}
                muted={true}
                controls={false}
                loop={false}
                onEnded={handleEventChange}
                config={{
                  file: {
                    attributes: {
                      playsInline: true, // Prevents fullscreen on iOS
                    },
                  },
                }}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
