import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { resultify } from '~/shared/lib/utils/resultify';

type updateStatusParam = {
  trnscId: string;
  refundTrnscId: string;
};
export const useUpdateRemitStatusMutation = (options?: MutationOptions<updateStatusParam, CBDCAxiosError, any>) => {
  const updateRemitStatus = (param: updateStatusParam) => {
    //임시 parameter
    return resultify(
      axios.post<string>(
        `${API_URLS.updateToRemitStatus}?trnscId=${param.trnscId}&refundTrnscId=${param.refundTrnscId}`,
      ),
    );
  };

  const mutation = useMutation<string, CBDCAxiosError, any>({
    ...options,
    mutationFn: (param: updateStatusParam) => updateRemitStatus(param),
  });

  return {
    ...mutation,
  };
};
